import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

function AdminLogin() {
  const [adminName, setAdminName] = useState("");
  const [adminPassword, setAdminPassword] = useState("");
  const [loading, setLoading] = useState(false); // Prevent multiple submits
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    const trimmedName = adminName.trim();
    const trimmedPassword = adminPassword.trim();

    if (!trimmedName || !trimmedPassword) {
      alert("Please enter Admin Name and Password");
      return;
    }

    setLoading(true);
    try {
      const res = await axios.post("http://localhost:5000/admin/login", {
        adminName: trimmedName,
        adminPassword: trimmedPassword,
      });

      console.log("Backend Response:", res.data);
      console.log("Status Code:", res.status);

      // Check for success (handles variations like {success: true} or {message: "Login successful"})
      if (res.status === 200 && (res.data.success || res.data.message?.includes("successful"))) {
        alert("Admin Login Successful");
        navigate("/admin-dashboard");
      } else {
        alert(res.data.message || "Invalid Admin Name or Password");
      }
    } catch (error) {
      console.error("Login Error:", error);
      if (error.response) {
        alert(`Server Error: ${error.response.status} - ${error.response.data?.message || "Check backend"}`);
      } else if (error.request) {
        alert("Network Error: Cannot reach server. Ensure backend is running on port 5000.");
      } else {
        alert("Unexpected Error: " + error.message);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.loginBox}>
        <h2>Admin Login</h2>
        <form onSubmit={handleLogin}>
          <input
            type="text"
            placeholder="Enter Admin Name"
            value={adminName}
            onChange={(e) => setAdminName(e.target.value)}
            style={styles.input}
            disabled={loading}
          />
          <input
            type="password"
            placeholder="Enter Admin Password"
            value={adminPassword}
            onChange={(e) => setAdminPassword(e.target.value)}
            style={styles.input}
            disabled={loading}
          />
          <button type="submit" style={styles.button} disabled={loading}>
            {loading ? "Logging in..." : "Login"}
          </button>
        </form>
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "100vh",
    background: "#f5f6fa",
  },
  loginBox: {
    width: "300px",
    padding: "30px",
    borderRadius: "8px",
    background: "white",
    boxShadow: "0 0 10px rgba(0,0,0,0.1)",
    textAlign: "center",
  },
  input: {
    width: "100%",
    padding: "10px",
    margin: "10px 0",
    border: "1px solid #ccc",
    borderRadius: "5px",
  },
  button: {
    width: "100%",
    padding: "10px",
    background: "#0984e3",
    color: "white",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  },
};

export default AdminLogin;
